			// lexical scorer so docs don't vanish when the doc FTS index can't open.
			scored, ok := rankDocsViaFTS(brainDir, docIdx, query, candidateLimit)
			if !ok {
				scored = rankDocsLexical(docIdx, query, candidateLimit)
