func rankDocsViaFTS(brainDir string, index docIndex, query string, limit int) ([]scoredDocRecord, bool) {
	if limit <= 0 {
		return nil, false
	}
	expr := historyFTSMatchExpr(query)
	if expr == "" {
		return nil, false
	}
	db, err := openDocFTS(brainDir, index)
	if err != nil {
		return nil, false
	}
	defer db.Close()
	rows, err := db.Query(`SELECT CAST(rec_order AS INTEGER), bm25(doc_fts) FROM doc_fts WHERE doc_fts MATCH ? ORDER BY bm25(doc_fts) LIMIT ?`, expr, limit*4)
	if err != nil {
		return nil, false
	}
	defer rows.Close()
	out := make([]scoredDocRecord, 0, limit*4)
	seen := map[string]struct{}{}
	rawScores := map[string]float64{}
	var topScore float64
	for rows.Next() {
		var order int
		var bm float64
		if err := rows.Scan(&order, &bm); err != nil {
			return nil, false
		}
		if order < 0 || order >= len(index.Records) {
			continue
		}
		score := -bm // bm is SQLite's negated BM25 (<= 0); -bm is positive, higher = better
		if topScore == 0 {
			topScore = score
		} else if score < docFTSRelevanceCutoff*topScore {
			break
		}
		rec := index.Records[order]
		if _, ok := seen[rec.ID]; ok {
			continue
		}
		seen[rec.ID] = struct{}{}
		rawScores[rec.ID] = score
		out = append(out, scoredDocRecord{Record: rec, Score: int(score*1000 + 0.5)})
		if len(out) >= limit*4 {
			break
		}
	}
	if rows.Err() != nil {
		return nil, false
	}
	sort.SliceStable(out, func(a, b int) bool {
		// Preserve SQLite's sub-millipoint BM25 precision for ordering. The
		// public integer score can round tiny equal matches to zero, which must
		// not erase the current-vs-historical trust discount.
		left := docTrustAdjustedScore(rawScores[out[a].Record.ID], out[a].Record.Historical)
		right := docTrustAdjustedScore(rawScores[out[b].Record.ID], out[b].Record.Historical)
		if left != right {
			return left > right
		}
		return out[a].Record.ID < out[b].Record.ID
	})
	if len(out) > limit {
		out = out[:limit]
	}
	return out, true
