item.stdout:
package cli

import (
	"context"
	"strings"
	"testing"
	"time"
)

// Two unbounded paths on the MCP surface: one outbound, one in time.
//
// Carries #187 and #188, reimplemented against current main â€” both patches
// conflict on pure line drift from #118/#156/#158.

// --- #187: outbound frames were never bounded ----------------------------
//
// Inbound frames have been bounded by maxMCPFrameBytes since framing was
// written. Outbound frames were not bounded at all: every use of
// maxMCPFrameBytes in mcp.go was on the read side. The retrieval surface grew
// its own 128 KiB budget, but the ~25 graph/semantic/status/pattern tools had
// none â€” so a wide call could build a response larger than any frame the peer
// will accept, and the client either drops the connection or blocks. Either
// way the caller learns nothing about why.

func TestAnOversizedToolResultIsRefusedWithAnActionableError(t *testing.T) {
	huge := strings.Repeat("x", maxMCPFrameBytes+1)

	_, err := mcpToolTextResult(context.Background(), "brain_impact", huge)
	if err == nil {
		t.Fatal("a result larger than the frame limit was returned instead of refused")
	}
	// The caller has to be able to act on this: it must name the tool, the
	// limit, and what to change.
	for _, want := range []string{"brain_impact", "MCP frame limit", "narrow the request"} {
		if !strings.Contains(err.Error(), want) {
			t.Fatalf("error is not actionable, missing %q: %v", want, err)
		}
	}
}

func TestAnOrdinaryToolResultIsUnaffected(t *testing.T) {
	result, err := mcpToolTextResult(context.Background(), "brain_status", "all good")
	if err != nil {
		t.Fatalf("an ordinary result was refused: %v", err)
	}
	content, ok := result["content"].([]map[string]any)
	if !ok || len(content) != 1 {
		t.Fatalf("result shape changed: %#v", result)
	}
	if content[0]["text"] != "all good" {
		t.Fatalf("result text = %v, want %q", content[0]["text"], "all good")
	}
	if content[0]["type"] != "text" {
		t.Fatalf("result type = %v, want \"text\"", content[0]["type"])
	}
}

// TestTheOutboundBoundIsTheResponseBudgetNotTheFrameLimit.
//
// The outbound bound started life as the frame limit, because the frame limit
// was the only number to hand. It is the wrong number: 4 MiB of JSON is roughly
// a million tokens, so everything short of it came back as a success no caller
// could use -- brain_dead_code at the advertised limit returned 3,401,455 bytes
// exactly that way. The bound is now the response budget, with the frame limit
// beneath it as the transport's own backstop.
func TestTheOutboundBoundIsTheResponseBudgetNotTheFrameLimit(t *testing.T) {
	// Well under the budget: untouched.
	if _, err := mcpToolTextResult(context.Background(), "brain_status", strings.Repeat("x", 4096)); err != nil {
		t.Fatalf("a result comfortably under the budget was refused: %v", err)
	}
	// Between the budget and the frame limit: no longer a silent success.
	betweenBudgetAndFrame := strings.Repeat("x", maxMCPFrameBytes-4096)
	if len(betweenBudgetAndFrame) <= mcpToolResponseMaxBytes {
		t.Fatalf("fixture %d bytes is not between the budget and the frame limit", len(betweenBudgetAndFrame))
	}
	if _, err := mcpToolTextResult(context.Background(), "brain_status", betweenBudgetAndFrame); err == nil {
		t.Fatal("a result under the frame limit but far over the response budget was returned as a plain success")
	}
	if _, err := mcpToolTextResult(context.Background(), "brain_status", strings.Repeat("x", maxMCPFrameBytes+1)); err == nil {
		t.Fatal("a result over the frame limit was accepted")
	}
}

// --- #188: brain_index_repository had no deadline -------------------------
//
package cli

import (
	"slices"
	"testing"
)

func TestRankFactsFusedPublicOraclePreservesTargetAndHardDistractor(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_EMBEDDER", "")
	t.Setenv("ENTIRE_BRAIN_FACTS_BM25", "")
	facts := loadFactsBM25PublicSnapshot(t)
	rr := newSemanticReranker(defaultEmbedder())
	if rr == nil {
		t.Skip("bundled semantic backend unavailable")
	}
	got := rankFactsFused(facts, factsBM25PublicOracleQuery, 6, false, rr)
	const target = "fact:30c6c2e4a031d91df16e4d27"
	const hardDistractor = "fact:32a34f711bb107845dc407c3"
	targetRank := rankOfFactID(got, target)
	distractorRank := rankOfFactID(got, hardDistractor)
	if targetRank != 1 {
		t.Fatalf("public oracle target rank=%d, want 1", targetRank)
	}
	if distractorRank != 3 {
		t.Fatalf("public hard distractor rank=%d, want 3", distractorRank)
	}
	if !rr.lastRun.QueryVectorValid || rr.lastRun.ValidCandidateVectors != len(facts) {
		t.Fatalf("public oracle unexpectedly degraded semantic coverage: %+v", rr.lastRun)
	}
}

func TestRankFactsFusedPublicSyntheticNullFailsClosed(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_EMBEDDER", "")
	t.Setenv("ENTIRE_BRAIN_FACTS_BM25", "")
	facts := loadFactsBM25PublicSnapshot(t)
	rr := newSemanticReranker(defaultEmbedder())
	if rr == nil {
		t.Skip("bundled semantic backend unavailable")
	}
	// This is a clearly synthetic corpus-closed null, not a relevance label.
	// Automatic semantic injection now fails closed when the nearest candidates
	// do not clear the corpus-relative calibration gate.
	got := rankFactsFused(facts, "xylophone zebra quokka", 6, false, rr)
	if len(got) != 0 {
		t.Fatalf("synthetic null returned semantic-only facts: %+v", got)
	}
}

func TestRankFactsFusedCalibrationSuppressesWeakSemanticTail(t *testing.T) {
	t.Setenv("ENTIRE_BRAIN_EMBEDDER", "")
	t.Setenv("ENTIRE_BRAIN_FACTS_BM25", "")
	facts := loadFactsBM25PublicSnapshot(t)
	rr := newSemanticReranker(defaultEmbedder())
	if rr == nil {
		t.Skip("bundled semantic backend unavailable")
	}
	const query = "why does the summary endpoint provide aggregates ignored by the command line"
	const target = "fact:32203deb1036cba4d14b243c"

	fullDepth := rankFactsFusedWithSemanticDepthMultiplier(facts, query, 6, false, rr, 0)
	if rank := rankOfFactID(fullDepth, target); rank == 0 {
		t.Fatal("calibration removed a strong lexical target at full semantic depth")
	}
	got := rankFactsFused(facts, query, 6, false, rr)
	if rank := rankOfFactID(got, target); rank == 0 {

	// Collect the heavy blobs (each also registers a content-addressed reference on
	// the wire manifest). Order within each kind is stable so re-publishing an
	// unchanged brain produces a byte-identical request (idempotent).
	var blobs []publishArtifact
	snapshots, err := collectSnapshotArtifacts(art, storage.BrainDir)
	if err != nil {
		return publishRequestBody{}, "", err
	}
	blobs = append(blobs, snapshots...)
	overlays, err := collectOverlayArtifacts(art, storage.BrainDir)
	if err != nil {
		return publishRequestBody{}, "", err
	}
	blobs = append(blobs, overlays...)
	facts, err := collectFactArtifacts(art, storage.BrainDir)
	if err != nil {
		return publishRequestBody{}, "", err
	}
	blobs = append(blobs, facts...)

	// The manifest artifact is the fully-built wire artifact (manifest header +
	// all references), addressed by the repo's HEAD commit (the store addresses a
	// manifest by commit).
	manifestData, err := json.Marshal(art)
	if err != nil {
		return publishRequestBody{}, "", fmt.Errorf("encode manifest: %w", err)
	}
	manifestArtifact := publishArtifact{
		Kind:   brainKindManifest,
		Ref:    publishManifestRef(ctx, opts, repoDir, manifest),
		Digest: contentDigest(manifestData),
		Data:   manifestData,
	}

	body := publishRequestBody{
		Artifacts: append([]publishArtifact{manifestArtifact}, blobs...),
	}
	// Preflight the total bundle size against the server's 256 MiB body cap BEFORE
	// json.Marshal base64-expands every blob into one buffer, so an oversized brain
	// fails with a precise local message instead of building a multi-GB body only to
	// be 413'd with an opaque error.
	if err := ensurePublishBodyWithinLimit(body); err != nil {
		return publishRequestBody{}, "", err
	}
	return body, repoKey, nil
}

