		if !run.Complete {
			out.PendingRuns++
		}
		if len(run.Limitations) > 0 {
			out.LimitedRuns++
		}
	}
	for _, ref := range st.Current {
		r := st.Snapshots[ref]
		if !visible(&st, r) {
			continue
		}
		out.Records++
		if now.Sub(r.ObservedAt) > 24*time.Hour {
			out.Stale++
		}
		if len(r.Completeness.Missing)+len(r.Completeness.Truncated)+len(r.Completeness.Limitations) > 0 {
			out.Incomplete++
		}
	}
	return out, nil
}

