	if s.Lock == nil || s.Write == nil {
		return errors.New("issue mutations require lock and atomic writer")
	}
	return s.Lock(func() error {
		st, err := s.Load()
		if err != nil {
			return err
		}
		if err = fn(&st); err != nil {
			return err
		}
		b, err := json.Marshal(st)
		if err != nil {
			return err
