func (s Store) Records() ([]Snapshot, error) {
	st, err := s.Load()
	if err != nil {
		return nil, err
	}
	out := []Snapshot{}
	for _, ref := range st.Current {
		r := st.Snapshots[ref]
		if visible(&st, r) {
			out = append(out, snapshotFor(&st, r, ref))
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Key() < out[j].Key() })
