	for _, run := range st.Runs {
		if run.Project != r.Project {
			continue
		}
		if !run.Complete {
			coverage["Project import has unfinished pagination; absence is not evidence of deletion."] = true
		}
		for _, v := range run.Limitations {
			coverage[v] = true
		}
