		return Snapshot{}, err
	}
	var out []Snapshot
	for _, r := range rs {
		if r.Kind == "issue" && (strings.EqualFold(r.Alias, value) || r.URL == value || r.ID == value || r.Key() == value) {
			out = append(out, r)
		}
	}
	if len(out) != 1 {
		return Snapshot{}, fmt.Errorf("issue %q resolved to %d records in selected projects", value, len(out))
	}
