		out = append(out, scoredDocRecord{Record: s.rec, Score: s.score})
		if len(out) >= limit {
			break
		}
	}
	return out
}

func rankDocsViaFTS(brainDir string, index docIndex, query string, limit int) ([]scoredDocRecord, bool) {
	if limit <= 0 {
		return nil, false
	}
	expr := historyFTSMatchExpr(query)
	if expr == "" {
		return nil, false
	}
	db, err := openDocFTS(brainDir, index)
	if err != nil {
		return nil, false
	}
	defer db.Close()
	rows, err := db.Query(`SELECT CAST(rec_order AS INTEGER), bm25(doc_fts) FROM doc_fts WHERE doc_fts MATCH ? ORDER BY bm25(doc_fts) LIMIT ?`, expr, limit*4)
	if err != nil {
		return nil, false
	}
	defer rows.Close()
	out := make([]scoredDocRecord, 0, limit*4)
	seen := map[string]struct{}{}
	rawScores := map[string]float64{}
	var topScore float64
	for rows.Next() {
		var order int
		var bm float64
		if err := rows.Scan(&order, &bm); err != nil {
			return nil, false
		}
		if order < 0 || order >= len(index.Records) {
			continue
		}
		score := -bm // bm is SQLite's negated BM25 (<= 0); -bm is positive, higher = better
		if topScore == 0 {
			topScore = score
		} else if score < docFTSRelevanceCutoff*topScore {
			break
		}
		rec := index.Records[order]
		if _, ok := seen[rec.ID]; ok {
			continue
		}
		seen[rec.ID] = struct{}{}
		rawScores[rec.ID] = score
		out = append(out, scoredDocRecord{Record: rec, Score: int(score*1000 + 0.5)})
		if len(out) >= limit*4 {
			break
		}
	}
	if rows.Err() != nil {
		return nil, false
	}
	sort.SliceStable(out, func(a, b int) bool {
		// Preserve SQLite's sub-millipoint BM25 precision for ordering. The
		// public integer score can round tiny equal matches to zero, which must
		// not erase the current-vs-historical trust discount.
				}
			}
		}
		out[name] = allowed
	}
	return out
}

func validateMCPToolArguments(tool string, args map[string]any) error {
	allowed, known := mcpToolAllowedArgs()[tool]
	if !known {
		return nil
	}
	for key := range args {
		if !allowed[key] {
			return mcpInvalidParams("unknown argument for %s: %s", tool, key)
		}
	}
	return nil
}

func mcpOptionalString(args map[string]any, key string) (string, error) {
	value, ok := args[key]
	if !ok || value == nil {
		return "", nil
	}
	typed, ok := value.(string)
	if !ok {
		return "", mcpInvalidParams("%s must be string", key)
	}
	// BOUND THE ECHO. A tool result repeats its own query/task/id back to the
	// caller, so an argument big enough to blow the response budget on its own
	// cannot be trimmed away by dropping rows: a 1 MB query produced a 1,000,201
	// byte result and a hard -32000, which made "a call at the schema maximum
	// always returns an answer" true for limits and false for strings. The
	// schemas declare this maxLength too, so a validating client sees it.
	if len(typed) > mcpStringArgMaxBytes {
		return "", mcpInvalidParams("%s must be at most %d bytes, got %d", key, mcpStringArgMaxBytes, len(typed))
	}
	return typed, nil
}

