	if found == nil {
		found = []unifiedResult{}
	}
	if missing == nil {
		missing = []string{}
	}
	if jsonOut {
		serialized, err := jsonOutputBytes(map[string]any{"branch": resolvedBranch, "results": found, "missing": missing})
		if err != nil {
			return nil, err
		}
		if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), serialized, privacyPolicy); err != nil {
			return nil, err
		}
		if len(factIDs) > 0 {
			recordReceipt()
		}
		return missing, nil
	}
	var rendered bytes.Buffer
	if err := writeTextToWriter(&rendered, func(out io.Writer) {
		for _, r := range found {
			label := r.Source
			if r.VerificationRequired {
				label += " verify"
			}
			fmt.Fprintf(out, "[%s] %s  %s\n%s\n", label, r.ID, unifiedResultLocation(r), r.Text)
			printRetrievalCaveats(out, r)
			printConversationTurns(out, r)
			fmt.Fprintln(out)
		}
		for _, id := range missing {
			fmt.Fprintf(out, "not found: %s\n", id)
		}
		// "not found" for an id the caller is already holding makes the same
		// claim the empty-result note makes: that the item was never there.
		// When the fact store cannot produce what the manifest declares, that
		// claim is wrong â€” and `get fact:<id>` is usually the exact moment a
		// user discovers the loss.
		if len(missing) > 0 {
			if integrity := inspectBrainFactStore(brainDir); !integrity.OK() {
				fmt.Fprintf(out, "note: \"not found\" is NOT evidence of absence â€” %s\n", integrity.Warning())
			}
		}
	}); err != nil {
		return nil, err
	}
	if err := writeRetrievalResponseBytes(cmd.OutOrStdout(), rendered.Bytes(), privacyPolicy); err != nil {
		return nil, err
	}
	if len(factIDs) > 0 {
		recordReceipt()
	}
	return missing, nil
}
"}

