package cli

import (
 "context"
 "encoding/json"
 "strings"
 "testing"
 "github.com/ashtom/entire-brain/internal/issues"
)

type reviewDisconnectEmbedder struct { run func() }
func (*reviewDisconnectEmbedder) ID() string {return "review"}
func (*reviewDisconnectEmbedder) Dim() int {return 2}
func (*reviewDisconnectEmbedder) Embed(string) []float32 {return []float32{1,0}}
func (e *reviewDisconnectEmbedder) EmbedQuery(string) []float32 { e.run(); return []float32{1,0} }

func TestReviewQueryDoesNotReturnPurgedEvidence(t *testing.T) {
 dir:=t.TempDir();seedIssueTest(t,dir)
 e:=&reviewDisconnectEmbedder{run:func(){if err:=issueStore(dir).Disconnect(issueTestProject,true);err!=nil {t.Fatal(err)}}}
 hits,err:=retrieveIssues(dir,"retry",5,modeVector,e)
 if err!=nil {t.Fatal(err)}
 if len(hits)>0 {t.Fatalf("query returned %d records after purge completed",len(hits))}
}

func TestReviewLargeSnapshotRemainsRetrievableOverMCP(t *testing.T) {
 f:=newBrainBriefProfileFixture(t); s:=seedIssueTest(t,f.brainDir)
 r:=s.Record; r.Text=strings.Repeat("evidence ",20000);r.UpdatedAt=r.UpdatedAt.AddDate(0,0,1)
 importIssueTest(t,f.brainDir,2,[]issues.Record{r})
 current,_,_:=issueStore(f.brainDir).Get(r.Key())
 raw,_:=json.Marshal(mcpToolCallParams{Name:"brain_get",Arguments:map[string]any{"id":current.Ref}})
 result,err:=handleMCPToolCall(context.Background(),f.opts,raw)
 if err!=nil {t.Fatal(err)}
 b,_:=json.Marshal(result)
 if !strings.Contains(string(b),current.Ref) {t.Fatalf("exact snapshot vanished from result: %s",b)}
}

package issues

import (
 "encoding/json"
 "testing"
 "time"
)

func TestReviewMoveKeepsUnchangedComments(t *testing.T) {
 s := fixture(t)
 const next = "77777777-7777-7777-7777-777777777777"
 if err := s.Configure(Binding{Version:1, Provider:"linear", Workspace:ws, Projects:[]string{project,next}}); err != nil { t.Fatal(err) }
 i,c := rec("issue",issue,"description"),rec("comment",comment,"unchanged comment")
 importOK(t,s,1,i,c)
 i.Project=next; i.UpdatedAt=now.Add(time.Hour); i.ObservedAt=i.UpdatedAt
 c.Project=next; c.ObservedAt=i.UpdatedAt
 result:=importOK(t,s,2,i,c)
 _,ok,err:=s.Get(c.Key())
 if err!=nil || !ok {t.Fatalf("comment lost after selected-project move: result=%+v found=%v err=%v",result,ok,err)}
}

func TestReviewProgressCoversEarlierBatches(t *testing.T) {
 s:=fixture(t)
 importOK(t,s,1,rec("issue",issue,"comment pages still not fetched"))
 var e Envelope
 _=json.Unmarshal(batch(2),&e)
 e.Progress=&Progress{Project:project,WindowStart:now.AddDate(0,0,-90),Issues:Page{Complete:true},Complete:true}
 b,_:=json.Marshal(e)
 if out,err:=s.Import(b);err==nil {t.Fatalf("declared run complete without comment pagination for earlier issue: %+v",out)}
}

func TestReviewCompleteRefreshRepairsPartialRecord(t *testing.T) {
 s:=fixture(t)
 r:=rec("issue",issue,"truncated")
 r.Completeness.Truncated=[]string{"description"}
 importOK(t,s,1,r)
 r.Text="truncated description now fetched in full";r.Completeness=Completeness{};r.ObservedAt=now.Add(time.Hour)
 result:=importOK(t,s,2,r)
 got,ok,err:=s.Get(r.Key())
 if err!=nil||!ok||got.Text!=r.Text {t.Fatalf("full refresh rejected: result=%+v got=%q err=%v",result,got.Text,err)}
}

