func (r Record) Group() string {
	if r.Kind == "comment" {
		return r.Workspace + ":" + r.Issue
	}
	return r.Workspace + ":" + r.ID
}
func Hash(data []byte) string { h := sha256.Sum256(data); return hex.EncodeToString(h[:]) }

