}
func Decode(data []byte, out any) error {
	if len(data) > MaxBatchBytes {
		return errors.New("issue input exceeds 2 MiB")
	}
	d := json.NewDecoder(bytes.NewReader(data))
	d.DisallowUnknownFields()
	if err := d.Decode(out); err != nil {
