				Concept: concepts[concept], ConversationID: evidenceIDs[concept], Rank: i + concept + 1,
				MatchedTerms: []string{strings.Repeat(string(rune('k'+concept)), 500)}, Arm: "lexical",
			}
		}
		results[i] = unifiedResult{
